steps.script:
$ErrorActionPreference='Stop'
$o=@{action='deploy_v2_private';state='started';repo='fabricelop/europapress-rss';worker='ttactualidad-v2-private-test';revision='a0d51f6e8a6e05e2e5011755905f5c8c951aecc5';secrets_untouched=$true;v1_untouched=$true}
try {
  $dir=Join-Path $env:TEMP 'ttactualidad-v2-private'
  if(!(Test-Path (Join-Path $dir '.git'))){throw 'REPO_MISSING'}
  Push-Location $dir
  try {
    $branch=(& git branch --show-current | Out-String).Trim()
    if($branch -ne 'feature/ttactualidad-v2-private-worker-20261114'){throw 'WRONG_BRANCH'}
    & git -c advice.detachedHead=false pull --ff-only origin feature/ttactualidad-v2-private-worker-20261114 *> $null
    if($LASTEXITCODE -ne 0){throw 'GIT_PULL_FAILED'}
    $sha=(& git rev-parse HEAD | Out-String).Trim()
    if($sha -ne 'a0d51f6e8a6e05e2e5011755905f5c8c951aecc5'){throw 'UNEXPECTED_REVISION'}
    Set-Location (Join-Path $dir 'v2\private-worker')
    $cfg=Get-Content -LiteralPath 'wrangler.jsonc' -Raw
    if(!$cfg.Contains('"name": "ttactualidad-v2-private-test"')){throw 'WORKER_NAME_MISMATCH'}
    $build=(& npm.cmd run build 2>&1 | Out-String)
    if($LASTEXITCODE -ne 0 -or !$build.Contains('TT_V2_PRIVATE_BUILD_READY=YES')){throw 'BUILD_FAILED'}
    $bundle=Get-Content -LiteralPath '.\dist\app.js' -Raw
    if(!$bundle.Contains('Radar · ') -or !$bundle.Contains('ttactualidad.rainyraven22.chatgpt.site')){throw 'BUILD_CONTENT_MISMATCH'}
    $deploy=(& npx.cmd wrangler deploy --keep-vars 2>&1 | Out-String)
    if($LASTEXITCODE -ne 0){throw 'DEPLOY_FAILED'}
    if(!$deploy.Contains('Deployed ttactualidad-v2-private-test')){throw 'DEPLOY_UNCONFIRMED'}
    $o.state='deployed';$o.version=$sha;$o.url='https://ttactualidad-v2-private-test.fabricelop.workers.dev'
  } finally {Pop-Location}
}catch {$o.state='failed';$o.error_class=$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
